  const bankNet = Number(branch.net || 0);
  const branchDeposit = round2(bankGross - abs(branchCommission) - abs(branchVat));
  const posCard = Number(posBranch.card ?? posBranch.card_receipt ?? 0);
  const diff = Math.round((bankGross - posCard) * 100) / 100;
  const ok = Math.abs(diff) <= tolerance;
  const machineLines = (branch.machines || []).map((machine) => '- ' + machine.terminal + ': AED ' + m(machine.gross) + ' (' + machine.count + ' trx)').join('\n');
  if (!ok) problems.push(branch.branch + ': difference AED ' + m(diff) + ' (Bank AED ' + m(bankGross) + ' vs POS Card AED ' + m(posCard) + ')');
  ownerLines.push((ok ? '✅' : '⚠️') + ' ' + branch.branch + ': Bank AED ' + m(bankGross) + ' | POS Card AED ' + m(posCard) + ' | Diff AED ' + m(diff));
  const branchMessage = '💳 Card Payment Reconciliation | تسوية مدفوعات البطاقة\n' +
    '📅 Date | التاريخ: ' + (analysis.period_label || analysis.from_date) + '\n' +
    '🏪 Branch | الفرع: ' + branch.branch + '\n\n' +
    '🏦 Bank/Card Machines Gross | إجمالي مكائن البطاقة:\nAED ' + m(bankGross) + '\n\n' +
    '🧾 POS Card Revenue | إيراد البطاقة في POS:\nAED ' + m(posCard) + '\n\n' +
    (ok ? '✅ Status | الحالة: Matched / مطابق' : '⚠️ Status | الحالة: Difference found / يوجد فرق') + '\n' +
    'Difference | الفرق: AED ' + m(diff) + '\n\n' +
    '💸 Commission | العمولة: AED ' + m(branchCommission) + '\n' +
    '🧾 VAT | الضريبة: AED ' + m(branchVat) + '\n' +
    '🏦 Bank deposit | المبلغ المودع في البنك:\nAED ' + m(branchDeposit || bankNet) + '\n' +
    'Formula | المعادلة: AED ' + m(bankGross) + ' - AED ' + m(abs(branchCommission)) + ' - AED ' + m(abs(branchVat)) + ' = AED ' + m(branchDeposit || bankNet) + '\n\n' +
    '🧮 Transactions | عدد العمليات: ' + branch.count + '\n\n' +
    'Machines | المكائن:\n' + machineLines + '\n\n' +
    (ok ? 'No action required. / لا يوجد إجراء مطلوب.' : 'Action required: review POS card payments, cancelled invoices, and terminal settlement. / يلزم مراجعة مدفوعات البطاقة في POS والفواتير الملغاة وتسوية المكائن.');
  outputs.push({ json: { type: 'branch', branch: branch.branch, recipient: recipients[key], message: branchMessage, analysis, pos_report: pos } });
}
if (problems.length) {
  recommendations.push('Review unpaid/cancelled card invoices for branches with differences.');
  recommendations.push('Check whether any card payments were posted to cash or another payment method in POS.');
  recommendations.push('Compare terminal settlement time with POS report time range 12:00 AM - 11:59 PM.');
} else {
  recommendations.push('All branch card totals match within tolerance. Keep daily reconciliation active.');
}
const totalGross = Number(analysis.pdf_grand_total ?? analysis.grand_total?.gross ?? 0);
const totalCommission = Number(analysis.pdf_commission ?? ((analysis.grand_total?.msf || 0) + (analysis.grand_total?.txn_fee || 0)));
const totalVat = Number(analysis.pdf_vat ?? analysis.grand_total?.vat ?? 0);
const totalDeposit = Number(analysis.bank_deposit_amount ?? analysis.net_payable ?? analysis.calculated_bank_deposit ?? analysis.grand_total?.net ?? 0);
const ownerMessage = '📊 Owner Card Payment Summary | ملخص تسوية البطاقة للمالك\n' +
  '📅 Date | التاريخ: ' + (analysis.period_label || analysis.from_date) + '\n\n' + ownerLines.join('\n') + '\n\n' +
  '🏦 Gross card total | إجمالي عمليات البطاقة: AED ' + m(totalGross) + '\n' +
  '💸 GRAND TOTAL VALUE OF COMMISSION | إجمالي العمولة: AED ' + m(totalCommission) + '\n' +
  '🧾 GRAND TOTAL VALUE OF VAT | إجمالي الضريبة: AED ' + m(totalVat) + '\n' +
  '🏦 Bank deposit | ما تم إيداعه في البنك: AED ' + m(totalDeposit) + '\n' +
  'Formula | المعادلة: AED ' + m(totalGross) + ' - AED ' + m(abs(totalCommission)) + ' - AED ' + m(abs(totalVat)) + ' = AED ' + m(totalDeposit) + '\n' +
  '🧮 Transactions | العمليات: ' + analysis.rows_count + '\n\n' +
  (problems.length ? '⚠️ Problems | المشاكل:\n- ' + problems.join('\n- ') : '✅ No material differences found. / لا توجد فروقات مهمة.') + '\n\n' +
  '💡 Recommendations | التوصيات:\n- ' + recommendations.join('\n- ');
outputs.push({ json: { type: 'owner', branch: 'Owner', recipient: recipients.OWNER, message: ownerMessage, analysis, pos_report: pos } });
return outputs;
